    async function runFullScan(sil=false,useBellman=false){const start=performance.now();const depth=parseInt(document.getElementById('pathInput').value)||5;if(!sil)log(`Scan depth ${depth}â€¦`);buildGraph();buildTriangles();State.opportunities={mega:[],triangular:[],bellman:[],suspicious:[]};const tri=scanTriangular();const bf=[];if(useBellman||(!sil&&document.getElementById('bellmanToggle')?.checked&&State.level>=5)){const minProfit=parseFloat(document.getElementById('minProfitInput')?.value)||0.0001;const targets=State.getTargetAssets();let found=false;const fallback=document.getElementById('fallbackCheck')?.checked;for(const t of targets){if(State.graph[t]){const res=bellmanFord(t,depth);if(res.length&&res.some(o=>o.profitPercent>=minProfit)){bf.push(...res.filter(o=>o.profitPercent>=minProfit));found=true;if(!fallback)break;}}}if(!found&&fallback){for(const t of targets){if(State.graph[t])bf.push(...bellmanFord(t,depth));}}}const all=[...tri,...bf];all.forEach(o=>{if(o.profitPercent>5)State.opportunities.mega.push(o);else if(o.type==='triangular')State.opportunities.triangular.push(o);else State.opportunities.bellman.push(o);});updateStats();if(!sil){['megaOpps','triangularOpps','bellmanOpps','suspiciousOpps'].forEach(id=>{document.getElementById(id).innerHTML='';});State.opportunities.mega.forEach(o=>UI.renderOpp(o,'megaOpps',true));State.opportunities.triangular.forEach(o=>UI.renderOpp(o,'triangularOpps'));State.opportunities.bellman.forEach(o=>UI.renderOpp(o,'bellmanOpps'));updateStatus(`âœ… ${all.length} opps`);}const duration=Math.round(performance.now()-start);State.operationLatency.push({op:'SCAN',duration});UI.renderLatency();State.save();if(State.graphRenderer&&document.getElementById('graphSlotContainer').style.display==='block'){State.computePurchasePower();State.graphRenderer.buildFromGraph(State.graph,State.opportunities,State.purchasePower,State.highlightedPaths,State.conflictEdges||new Set());}}
