    .tier-badge { display: inline-block; padding: 1px 4px; border-radius: 2px; font-size: calc(var(--base-font-size)*0.6); color: #000; margin-left: 2px; }
    .tier-pico { background: #ffaa00; } .tier-femto { background: #ff00ff; } .tier-planck { background: #00f0ff; }
    .progress-bar { height: 6px; background: #333; border-radius: 3px; margin: 3px 0; }
    .progress-fill { height: 100%; background: var(--gold); border-radius: 3px; width: 0%; }
    .perk-unlocked { color: var(--green); } .perk-locked { color: #ff4444; text-decoration: line-through; }
    #graphSlotContainer {
      display: none; background: linear-gradient(180deg, #0a0a1a, #1a0a2a);
      border: 3px solid var(--gold); border-radius: 14px; padding: 12px; margin: 10px 0;
      text-align: center; box-shadow: 0 0 30px rgba(255,215,0,0.3); position: relative; overflow: hidden;
    }
    #graphNetwork { display: block; margin: 0 auto; position: relative; z-index: 2; }
    #batchResult {
      background: #0a0a1a; border: 1px solid var(--gold); border-radius: 6px;
      padding: 8px; margin-top: 8px; font-size: calc(var(--base-font-size)*0.8);
      max-height: 250px; overflow-y: auto; text-align: left; position: relative; z-index: 2;
    }
    #batchHistory {
      background: #0a0a1a; border: 1px solid var(--cyan); border-radius: 6px;
      padding: 8px; margin-top: 8px; font-size: calc(var(--base-font-size)*0.7);
      max-height: 150px; overflow-y: auto; text-align: left; position: relative; z-index: 2;
    }
    .target-preset {
      border: 1px solid var(--cyan); padding: 2px 6px; border-radius: 10px;
      cursor: pointer; font-size: calc(var(--base-font-size)*0.7); color: var(--cyan); background: transparent;
    }
    .target-preset:hover { background: var(--cyan); color: #000; }
    .tooltip { position: relative; display: inline-block; cursor: help; color: var(--gold); }
    .tooltip .tooltiptext {
      visibility: hidden; width: 200px; background: #1a1a2a; color: #fff;
      text-align: center; border-radius: 6px; padding: 5px; position: absolute; z-index: 10;
      bottom: 125%; left: 50%; margin-left: -100px; opacity: 0; transition: opacity 0.3s;
      font-size: calc(var(--base-font-size)*0.7);
    }
    .tooltip:hover .tooltiptext { visibility: visible; opacity: 1; }
    .panel {
      background: var(--card); border-radius: 8px; padding: 10px; margin: 6px 0;
      border: 1px solid var(--border); display: none;
    }
    .panel h3 { color: var(--cyan); font-size: calc(var(--base-font-size)*1.1); margin-bottom: 6px; }
    .panel textarea {
      width: 100%; background: #0a0a1a; color: var(--cyan); border: 1px solid var(--cyan);
